|| \frac{(\ell+1)(\ell+2)}{2} -\frac{(\ell-m+1)(\ell-m+2)}{2}-\frac{(\ell-n+1)(\ell-n+2)}{2} | 3teil2=+ \frac{(\ell-m-n+1)(\ell-m-n+2)}{2}
|| \frac{2- (-m+1)(-m+2) - (-n+1)(-n+2) +(-m-n+1)(-m-n+2)}{2}
